    {
      "path": "plugins/deepseek-harness/packages/dsh-k8e-sandbox/src/index.ts",
      "content": "/**\n * Shared ownership of one k8e-sandbox session. Capability adapters await the\n * same session handle, so filesystem and process operations inhabit one remote\n * Linux world (mirrors the E2B POC's `ctx.e2b` owner).\n *\n * Transport: when an endpoint is configured (explicit, env, or the CLI\n * profiles.yaml KIP-17), a persistent `GrpcK8eClient` owns one connection and\n * every fs/exec op is a gRPC RPC on it — no per-op `k8e-sandbox-cli` spawn.\n * Without an endpoint the CLI-backed transport is used (local auto-discovery).\n * Session creation is single-flighted and failures are negatively cached so a\n * dead gateway cannot cause a getSession() storm.\n * @module @k8e-sandbox/dsh-k8e-sandbox\n */\n\nimport { Context, Service } from '@deepseek-ai/cordis'\nimport z from '@deepseek-ai/schemastery'\nimport { CliK8eClient, resolveSandboxTransport, type SandboxTransport } from '@k8e-sandbox/dsh-k8e-sandbox-client'\nimport { GrpcK8eClient } from '@k8e-sandbox/dsh-k8e-sandbox-client/grpc'\n\n/** Configuration for the shared k8e-sandbox owner. */\nexport interface Config {\n  /** gRPC gateway endpoint; unset resolves via env → ~/.k8e/sandbox/profiles.yaml (KIP-17). */\n  endpoint?: string\n  /** Named profile from ~/.k8e/sandbox/profiles.yaml (KIP-17). */\n  profile?: string\n  /** mTLS material dir for the direct gRPC terminal client. */\n  certDir?: string\n  /** Remote working directory shared by provider adapters. */\n  cwd?: string\n  /** RuntimeClass for the session pod. */\n  runtimeClass?: string\n  /** Explicit cross-process session reuse tenant; unset = one session per dsh session. */\n  tenant?: string\n  /** Egress allowlist (only applied when the owner creates the session). */\n  allowedHosts?: string[]\n  /** Dispose by pausing instead of destroying (PVC retained); Phase 1 destroy-only. */\n  pauseOnDispose?: boolean\n  /** How long a failed session creation stays negatively cached (ms). */\n  sessionFailureTtlMs?: number\n}\n\ninterface ResolvedConfig {\n  cwd: string\n  runtimeClass: string\n  tenant?: string\n  allowedHosts?: string[]\n  pauseOnDispose: boolean\n  sessionFailureTtlMs: number\n}\n\ninterface SchemaResolvedConfig extends Config {\n  cwd: string\n  runtimeClass: string\n  pauseOnDispose: boolean\n}\n\ndeclare module '@deepseek-ai/cordis' {\n  interface Context {\n    k8eSandbox: K8eSandboxRuntime\n  }\n}\n\n/** Creates one lazily consumable k8e-sandbox session and destroys it on disposal. */\nexport class K8eSandboxRuntime extends Service {\n  static Config: z<Config> = z.object({\n    endpoint: z.string(),\n    profile: z.string(),\n    certDir: z.string(),\n    cwd: z.string().default('/workspace'),\n    runtimeClass: z.string().default('gvisor'),\n    tenant: z.string(),\n    allowedHosts: z.array(z.string()),\n    pauseOnDispose: z.boolean().default(false),\n    sessionFailureTtlMs: z.number().default(10_000),\n  })\n\n  /** Validated remote working directory shared by provider adapters. */\n  readonly cwd: string\n  /** gRPC gateway endpoint (undefined = CLI local auto-discovery). */\n  readonly endpoint: string | undefined\n  /** Where the endpoint came from: config | env | profile | undefined. */\n  readonly endpointSource: 'config' | 'env' | 'profile' | undefined\n  /** Selected profile name when the endpoint came from profiles.yaml (KIP-17). */\n  readonly endpointProfile: string | undefined\n  /** mTLS material dir for the direct gRPC terminal client. */\n  readonly certDir: string | undefined\n  /** RuntimeClass for the session pod (deployment default from config). */\n  readonly runtimeClass: string\n\n  private readonly config: ResolvedConfig\n  private runtimeOverride: string | undefined\n  private readonly transport: SandboxTransport\n  private readonly grpcClient: GrpcK8eClient | undefined\n  private sessionId: string | undefined\n  private sessionInFlight: Promise<string> | undefined\n  private sessionUnavailableUntil = 0\n  private disposed = false\n\n  constructor(ctx: Context, config: Config) {\n    super(ctx, 'k8eSandbox')\n    // Schemastery fills defaulted fields before construction; the type does not encode that step.\n    const resolved = config as SchemaResolvedConfig\n    this.config = {\n      cwd: resolved.cwd,\n      runtimeClass: resolved.runtimeClass,\n      ...(config.tenant !== undefined ? { tenant: config.tenant } : {}),\n      ...(config.allowedHosts !== undefined ? { allowedHosts: config.allowedHosts } : {}),\n      pauseOnDispose: resolved.pauseOnDispose,\n      sessionFailureTtlMs: resolved.sessionFailureTtlMs ?? 10_000,\n    }\n    this.cwd = this.config.cwd\n    this.runtimeClass = this.config.runtimeClass\n    this.runtimeOverride = undefined\n\n    // Resolve the gateway: explicit config → env → CLI profiles.yaml (KIP-17).\n    const transportCfg = resolveSandboxTransport({\n      ...(config.endpoint !== undefined ? { endpoint: config.endpoint } : {}),\n      ...(config.certDir !== undefined ? { certDir: config.certDir } : {}),\n      ...(config.profile !== undefined ? { profile: config.profile } : {}),\n    })\n    this.endpoint = transportCfg?.endpoint\n    this.endpointSource = transportCfg?.source\n    this.endpointProfile = transportCfg?.profile\n    this.certDir = transportCfg?.certDir\n\n    if (transportCfg !== undefined) {\n      // Persistent gRPC connection: fs/exec ops become RPCs, no per-op CLI spawn.\n      this.grpcClient = new GrpcK8eClient({\n        endpoint: transportCfg.endpoint,\n        ...(transportCfg.certDir !== undefined ? { certDir: transportCfg.certDir } : {}),\n      })\n      this.transport = this.grpcClient\n    } else {\n      this.grpcClient = undefined\n      this.transport = new CliK8eClient({\n        ...(process.env.K8E_SANDBOX_CLI_BIN !== undefined ? { bin: process.env.K8E_SANDBOX_CLI_BIN } : {}),\n        ...(config.profile !== undefined ? { profile: config.profile } : {}),\n        ...(config.endpoint !== undefined ? { endpoint: config.endpoint } : {}),\n      })\n    }\n\n    ctx.effect(() => async () => {\n      this.disposed = true\n      // Always release the persistent gRPC connection, even when no session\n      // was ever assigned (disposal before first use must not leak the\n      // channel; the session pod is also reclaimed by the warm-pool GC).\n      if (this.sessionId !== undefined) {\n        try {\n          await this.transport.destroySession(this.sessionId)\n        } catch (_destroyFailure) {\n          // Best-effort: the session pod is also reclaimed by the warm-pool GC.\n        }\n      }\n      this.transport.close?.()\n    }, 'k8e sandbox teardown')\n  }\n\n  /**\n   * Return the live session id, creating the sandbox session on first use.\n   * Concurrent callers share one in-flight creation; a failed creation is\n   * negatively cached for `sessionFailureTtlMs` so a dead gateway fails fast\n   * on subsequent probes instead of re-dialing create every time.\n   * @throws when the service is disposing or the gateway is unreachable.\n   */\n  async getSession(): Promise<string> {\n    if (this.disposed) throw new Error('k8e sandbox service is disposing')\n    if (this.sessionId !== undefined) return this.sessionId\n    const now = Date.now()\n    if (this.sessionUnavailableUntil > now) {\n      const retryIn = Math.ceil((this.sessionUnavailableUntil - now) / 1000)\n      throw new Error(`k8e sandbox: session unavailable (gateway unreachable), retry in ${retryIn}s`)\n    }\n    if (this.sessionInFlight !== undefined) return this.sessionInFlight\n    this.sessionInFlight = this.createSessionOnce().finally(() => {\n      this.sessionInFlight = undefined\n    })\n    return this.sessionInFlight\n  }\n\n  private async createSessionOnce(): Promise<string> {\n    try {\n      const created = await this.transport.createSession({\n        runtimeClass: this.effectiveRuntimeClass,\n        ...(this.config.tenant !== undefined ? { tenant: this.config.tenant } : {}),\n        ...(this.config.allowedHosts !== undefined ? { allowedHosts: this.config.allowedHosts } : {}),\n      })\n      if (this.disposed) {\n        await this.transport.destroySession(created.sessionId).catch(() => undefined)\n        throw new Error('k8e sandbox service is disposing')\n      }\n      this.sessionId = created.sessionId\n      return this.sessionId\n    } catch (err) {\n      this.sessionUnavailableUntil = Date.now() + this.config.sessionFailureTtlMs\n      throw err\n    }\n  }\n\n  /**\n   * Override the RuntimeClass for NEW sessions (L1 web prefs). `undefined`\n   * clears the override and falls back to the deployment config default.\n   * Existing sessions are never migrated — matches warm-pool per-runtime\n   * splitting semantics (sandbox.k8e.io/runtime-class label).\n   */\n  applyRuntimeClass(runtimeClass: string | undefined): void {\n    this.runtimeOverride = runtimeClass\n  }\n\n  /** RuntimeClass the next session creation will use (override ?? config default). */\n  get effectiveRuntimeClass(): string {\n    return this.runtimeOverride ?? this.config.runtimeClass\n  }\n\n  /** Where `effectiveRuntimeClass` comes from: L1 web prefs or deployment config. */\n  get runtimeClassSource(): 'prefs' | 'config' {\n    return this.runtimeOverride !== undefined ? 'prefs' : 'config'\n  }\n\n  /** Return the shared transport client (persistent gRPC when an endpoint is resolved). */\n  getClient(): SandboxTransport {\n    return this.transport\n  }\n\n  /**\n   * Return the direct gRPC client for the terminal primitive. Requires a\n   * resolved endpoint (explicit, env, or profile).\n   * @throws when no endpoint is configured.\n   */\n  getGrpcClient(): GrpcK8eClient {\n    if (this.grpcClient === undefined) {\n      throw new Error('k8e sandbox: gRPC terminal requires an endpoint (config, K8E_SANDBOX_ENDPOINT, or profiles.yaml)')\n    }\n    return this.grpcClient\n  }\n}\n\nexport default K8eSandboxRuntime\n"
    },
    {
      "path": "plugins/deepseek-harness/packages/dsh-k8e-sandbox-tool/src/index.ts",
      "content": "/**\n * k8e-sandbox model-surface tools for DeepSeek Harness (KIP-20 Phase 2):\n * sandbox-only lifecycle verbs exposed on `ctx.tools` — session\n * create/status/destroy, foreground exec, background exec + poll. The\n * fs/subprocess seams cover file and process primitives; these tools expose\n * the k8e lifecycle verbs those seams cannot express (the \"third corner\" of\n * the seam model).\n * @module @k8e-sandbox/dsh-k8e-sandbox-tool\n */\n\nimport type { Context } from '@deepseek-ai/cordis'\nimport { Service } from '@deepseek-ai/cordis'\nimport type { ContentBlock } from '@deepseek-ai/dsh-llm'\nimport { defineTool } from '@deepseek-ai/dsh-tools'\nimport type { ParameterSchemaSpec } from '@deepseek-ai/dsh-tools'\nimport type { K8eSandboxRuntime } from '@k8e-sandbox/dsh-k8e-sandbox'\n\n/** Strict object output schema (lossless canonical JSON). */\nfunction resultSchema<const S extends ParameterSchemaSpec>(properties: S) {\n  return { type: 'object', additionalProperties: false, properties } as const\n}\n\n/** Output fields shared by foreground exec and background poll results. */\nconst execResultProps = {\n  stdout: { type: 'string' },\n  stderr: { type: 'string' },\n  exitCode: { type: 'number' },\n  durationMs: { type: 'number' },\n  truncated: { type: 'boolean' },\n} as const\n\n/** Pure Native rendering of one validated canonical value. */\nfunction renderValue(_args: unknown, value: unknown): ContentBlock[] {\n  return [{ type: 'text', text: JSON.stringify(value) }]\n}\n\n/**\n * k8e-sandbox tools provider registered as `ctx.k8eSandboxTools`. It shares\n * the session owned by `ctx.k8eSandbox` (KIP-20): the owner lazily creates\n * the session on first use, and every tool here operates on it.\n */\nexport class K8eSandboxTools extends Service {\n  static readonly inject = ['k8eSandbox', 'tools']\n\n  constructor(ctx: Context) {\n    super(ctx, 'k8eSandboxTools')\n    // Cordis constructs class plugins as `new Cls(ctx, config)` — the second\n    // parameter is the plugin config, NOT an injected dependency. Resolve the\n    // owner from ctx like the fs/subprocess seams; guard for an actionable\n    // error when the bundle is not actually loaded.\n    const runtime = (): K8eSandboxRuntime => {\n      const owner = this.ctx.k8eSandbox\n      if (owner === undefined) {\n        throw new Error('k8e-sandbox: ctx.k8eSandbox is not mounted — the dsh-k8e-sandbox bundle is not loaded; reinstall the bundle and restart dsh (k8e-sandbox-cli doctor --fix diagnoses this)')\n      }\n      return owner\n    }\n\n    ctx.tools.register(defineTool({\n      name: 'k8e_sandbox_session_status',\n      description: 'Show the current k8e-sandbox session: creates one on first use (shared with fs/subprocess) and reports availability, session id, tenant and pod reachability.',\n      parameters: {},\n      output: {\n        schema: resultSchema({\n          available: { type: 'boolean' },\n          sessionId: { type: 'string' },\n          tenantId: { type: 'string' },\n          error: { type: 'string' },\n        }),\n        render: renderValue,\n      },\n      async execute() {\n        const client = runtime().getClient()\n        return client.status()\n      },\n    }))\n\n    ctx.tools.register(defineTool({\n      name: 'k8e_sandbox_session_destroy',\n      description: 'Destroy the current k8e-sandbox session (releases the pod; PVC/workspace semantics per session config). Idempotent.',\n      parameters: {},\n      output: { schema: resultSchema({ destroyed: { type: 'boolean' } }), render: renderValue },\n      async execute() {\n        const client = runtime().getClient()\n        const st = await client.status()\n        if (st.sessionId && st.sessionId !== '') {\n          await client.destroySession(st.sessionId)\n        }\n        return { destroyed: true }\n      },\n    }))\n\n    ctx.tools.register(defineTool({\n      name: 'k8e_sandbox_exec',\n      description: 'Run a command in the k8e sandbox session and return its output, exit code and duration. Use for quick foreground checks; use k8e_sandbox_run_background for long tasks.',\n      parameters: {\n        code: { type: 'string', required: true, description: 'Command or code to run' },\n        lang: { type: 'string', description: 'Language hint: bash (default), python, node, ts' },\n        timeout: { type: 'number', description: 'Timeout in seconds' },\n      },\n      output: {\n        schema: resultSchema({\n          ...execResultProps,\n        }),\n        render: renderValue,\n      },\n      async execute(args) {\n        const client = runtime().getClient()\n        const result = await client.run(args.code, {\n          ...(args.lang !== undefined ? { lang: args.lang } : {}),\n          ...(args.timeout !== undefined ? { timeout: args.timeout } : {}),\n          sessionId: await runtime().getSession(),\n        })\n        // The transport result carries extra fields (sessionId/status/language);\n        // the tool schema is strict (additionalProperties: false), so return\n        // exactly the declared shape.\n        return {\n          stdout: result.stdout,\n          stderr: result.stderr,\n          exitCode: result.exitCode,\n          durationMs: Number(result.durationMs) || 0,\n          truncated: result.truncated,\n        }\n      },\n    }))\n\n    ctx.tools.register(defineTool({\n      name: 'k8e_sandbox_run_background',\n      description: 'Submit a command to run asynchronously in the k8e sandbox and return its run id immediately; poll with k8e_sandbox_poll. Use for long-running or streaming workloads.',\n      parameters: {\n        code: { type: 'string', required: true, description: 'Command or code to run in the background' },\n        lang: { type: 'string', description: 'Language hint: bash (default), python, node, ts' },\n      },\n      output: {\n        schema: resultSchema({\n          runId: { type: 'string' },\n          sessionId: { type: 'string' },\n          status: { type: 'string' },\n        }),\n        render: renderValue,\n      },\n      async execute(args) {\n        const client = runtime().getClient()\n        const sessionId = await runtime().getSession()\n        const res = await client.runBackground(args.code, {\n          ...(args.lang !== undefined ? { lang: args.lang } : {}),\n          sessionId,\n        })\n        return { runId: res.runId, sessionId, status: 'submitted' }\n      },\n    }))\n\n    ctx.tools.register(defineTool({\n      name: 'k8e_sandbox_poll',\n      description: 'Poll a background run (from k8e_sandbox_run_background) and return its status, output and exit code once it finishes.',\n      parameters: {\n        runId: { type: 'string', required: true, description: 'Run id returned by k8e_sandbox_run_background' },\n      },\n      output: {\n        schema: resultSchema({\n          runId: { type: 'string' },\n          status: { type: 'string' },\n          ...execResultProps,\n        }),\n        render: renderValue,\n      },\n      async execute(args) {\n        const client = runtime().getClient()\n        const result = await client.poll(args.runId)\n        return {\n          runId: result.runId,\n          status: result.status,\n          stdout: result.stdout,\n          stderr: result.stderr,\n          exitCode: result.exitCode,\n          durationMs: Number(result.durationMs) || 0,\n          truncated: result.truncated,\n        }\n      },\n    }))\n\n    // ── KIP-24 service exposure + egress allowlist ──────────────────────────\n\n    ctx.tools.register(defineTool({\n      name: 'k8e_sandbox_expose',\n      description: 'Expose an in-sandbox service port through the k8e API Gateway and return its public URL (http(s)://<gateway>/k8e/expose/<session>/<port>/). Use after starting a long-running service (e.g. a web server) in the sandbox. Teardown with k8e_sandbox_unexpose.',\n      parameters: {\n        port: { type: 'number', required: true, description: 'In-sandbox service port to expose (1-65535)' },\n        host: { type: 'string', description: 'In-sandbox listen address (default 127.0.0.1)' },\n      },\n      output: {\n        schema: resultSchema({\n          url: { type: 'string' },\n          port: { type: 'number' },\n        }),\n        render: renderValue,\n      },\n      async execute(args) {\n        // Exposure is a GATEWAY operation: dial it directly over gRPC.\n        // The CLI-backed transport would spawn k8e-sandbox-cli INSIDE the\n        // sandbox (web-terminal deployments), where the binary does not exist.\n        const grpc = runtime().getGrpcClient()\n        const sessionId = await runtime().getSession()\n        const res = await grpc.exposeService(sessionId, args.port, args.host)\n        return { url: res.url, port: args.port }\n      },\n    }))\n\n    ctx.tools.register(defineTool({\n      name: 'k8e_sandbox_unexpose',\n      description: 'Remove a public tunnel for an in-sandbox service port (stops k8e_sandbox_expose). Idempotent: unexposing a port that is not exposed returns ok=false.',\n      parameters: {\n        port: { type: 'number', required: true, description: 'In-sandbox service port to unexpose' },\n      },\n      output: {\n        schema: resultSchema({\n          ok: { type: 'boolean' },\n          port: { type: 'number' },\n        }),\n        render: renderValue,\n      },\n      async execute(args) {\n        const grpc = runtime().getGrpcClient()\n        const sessionId = await runtime().getSession()\n        const res = await grpc.unexposeService(sessionId, args.port)\n        return { ok: res.ok, port: args.port }\n      },\n    }))\n\n    ctx.tools.register(defineTool({\n      name: 'k8e_sandbox_allow_hosts',\n      description: 'Freely configure the sandbox session egress allowlist (allowedHosts) — applies live to NEW connections (CNP re-apply). Use to grant/revoke outbound access to domains, e.g. package registries or tunnel endpoints.',\n      parameters: {\n        hosts: { type: 'array', items: { type: 'string' }, required: true, description: 'Full replacement allowlist; empty array clears it (falls back to cluster defaults)' },\n      },\n      output: {\n        schema: resultSchema({\n          hosts: { type: 'array', items: { type: 'string' } },\n        }),\n        render: renderValue,\n      },\n      async execute(args) {\n        const grpc = runtime().getGrpcClient()\n        const sessionId = await runtime().getSession()\n        const hosts = await grpc.updateAllowedHosts(sessionId, args.hosts ?? [])\n        return { hosts }\n      },\n    }))\n  }\n}\n\nexport default K8eSandboxTools\n"
    },
    {
      "path": "plugins/deepseek-harness/packages/dsh-k8e-sandbox-fs/src/index.ts",
      "content": "/**\n * k8e-sandbox Service Provider for the filesystem capability seam.\n *\n * Two path worlds, one provider:\n * - Workspace paths (relative, or under the sandbox root e.g. `/workspace`)\n *   live in the sandbox pod and go through the shared transport (persistent\n *   gRPC when an endpoint is resolved — no per-op CLI spawn).\n * - Host-absolute paths outside the sandbox root (e.g. `/Users/...` used by\n *   agent-instructions / skill discovery preflight) stay on the local disk:\n *   AGENTS.md / skills discovery must not pay a pod round trip before the\n *   first model request (KIP-20 perf follow-up).\n *\n * listDir uses the gateway's ListFiles entry facts (type/size) when present —\n * no per-child stat — and falls back to a single exec probe per child only\n * when the gateway predates entry facts.\n * @module @k8e-sandbox/dsh-k8e-sandbox-fs\n */\n\nimport { Buffer } from 'node:buffer'\nimport { readdir, readFile, stat, writeFile } from 'node:fs/promises'\nimport { posix } from 'node:path'\nimport { Context } from '@deepseek-ai/cordis'\nimport { FileSystem, FsError, FsTargetKey, FsVersion } from '@deepseek-ai/dsh-fs'\nimport type {\n  FsDirEntry,\n  FsEditOutcome,\n  FsEditRequest,\n  FsInfo,\n  FsPathInfo,\n  FsTarget,\n  FsWriteIntent,\n  FsWriteOutcome,\n} from '@deepseek-ai/dsh-fs'\nimport type { K8eSandboxRuntime } from '@k8e-sandbox/dsh-k8e-sandbox'\n\n/** Stat facts returned by the single `stat -c` probe. */\ninterface StatFacts {\n  type: FsInfo['type']\n  size: number\n  version: ReturnType<typeof FsVersion>\n}\n\nfunction hostType(info: { isFile(): boolean; isDirectory(): boolean; isSymbolicLink(): boolean }): FsInfo['type'] {\n  return info.isDirectory() ? 'directory' : info.isFile() ? 'file' : 'other'\n}\n\n/** Remote filesystem backend sharing the session owned by `ctx.k8eSandbox`. */\nexport class K8eFileSystem extends FileSystem {\n  static inject = ['k8eSandbox']\n\n  /**\n   * The owning sandbox service. A missing `ctx.k8eSandbox` means the owner\n   * did not mount before this seam was used (stale dsh process after a bundle\n   * upgrade, or the bundle is not in dsh.profile.bundles) — surface an\n   * actionable error instead of a bare TypeError.\n   */\n  private owner(): K8eSandboxRuntime {\n    const owner = this.ctx.k8eSandbox\n    if (owner === undefined) {\n      throw new Error('k8e-sandbox: ctx.k8eSandbox is not mounted — the dsh-k8e-sandbox bundle is not loaded; reinstall the bundle and restart dsh (k8e-sandbox-cli doctor --fix diagnoses this)')\n    }\n    return owner\n  }\n\n  private async runtime(): Promise<K8eSandboxRuntime> {\n    return this.owner()\n  }\n\n  private async session(): Promise<string> {\n    return (await this.runtime()).getSession()\n  }\n\n  private display(path: string, cwd?: string): string {\n    return posix.resolve(cwd ?? this.owner().cwd, path)\n  }\n\n  /**\n   * True when the path lives in the sandbox workspace. Relative paths resolve\n   * under the sandbox root; absolute paths must be under it. Host-absolute\n   * paths (preflight: AGENTS.md / skills discovery) stay on the local disk.\n   */\n  private isSandboxPath(path: string): boolean {\n    if (!posix.isAbsolute(path)) return true\n    const root = this.owner().cwd\n    return path === root || path.startsWith(`${root}/`)\n  }\n\n  private shellQuote(value: string): string {\n    return `'${value.replaceAll('\\'', `'\"'\"'`)}'`\n  }\n\n  override async resolve(path: string, opts?: { cwd?: string; signal?: AbortSignal }): Promise<FsTarget> {\n    if (path.trim().length === 0) throw new FsError('file_path must be a non-empty string', 'FS_NOT_FOUND')\n    const displayPath = this.display(path, opts?.cwd)\n    // Phase 1: no realpath round-trip; the canonical path is the resolved path.\n    return { targetKey: FsTargetKey(displayPath), displayPath }\n  }\n\n  override processPath(target: FsTarget): string {\n    return String(target.targetKey)\n  }\n\n  override fileUrl(target: FsTarget): string {\n    const path = this.processPath(target)\n    return `file://${path.split('/').map((segment) => encodeURIComponent(segment)).join('/')}`\n  }\n\n  override contains(parent: FsTarget, child: FsTarget): boolean {\n    const relative = posix.relative(this.processPath(parent), this.processPath(child))\n    return relative === '' || (relative !== '..' && !relative.startsWith('../') && !posix.isAbsolute(relative))\n  }\n\n  // ── Local (host) implementation for preflight paths ────────────────────────\n\n  private async localStat(path: string): Promise<StatFacts | undefined> {\n    try {\n      const info = await stat(path)\n      return {\n        type: hostType(info),\n        size: info.size,\n        version: FsVersion(`host:${Math.trunc(info.mtimeMs)}:${info.size}`),\n      }\n    } catch {\n      return undefined\n    }\n  }\n\n  private async localListDir(path: string): Promise<FsDirEntry[]> {\n    const entries: FsDirEntry[] = []\n    const dirents = await readdir(path, { withFileTypes: true })\n    for (const dirent of dirents) {\n      const childPath = posix.join(path, dirent.name)\n      const type: FsInfo['type'] = dirent.isDirectory() ? 'directory' : dirent.isFile() ? 'file' : 'other'\n      let size: number | undefined\n      let version: ReturnType<typeof FsVersion> | undefined\n      if (type === 'file') {\n        try {\n          const info = await stat(childPath)\n          size = info.size\n          version = FsVersion(`host:${Math.trunc(info.mtimeMs)}:${info.size}`)\n        } catch {\n          // vanished between readdir and stat → skip entry facts\n        }\n      }\n      entries.push({\n        name: dirent.name,\n        type,\n        target: { targetKey: FsTargetKey(childPath), displayPath: childPath },\n        ...(size !== undefined ? { size } : {}),\n        ...(version !== undefined ? { version } : {}),\n      })\n    }\n    return entries.sort((left, right) => left.name.localeCompare(right.name))\n  }\n\n  private async localReadText(path: string): Promise<string> {\n    return readFile(path, 'utf8')\n  }\n\n  private async localWriteText(path: string, content: string): Promise<void> {\n    await writeFile(path, content, 'utf8')\n  }\n\n  // ── Sandbox (remote) implementation ───────────────────────────────────────\n\n  private async probe(path: string): Promise<StatFacts | undefined> {\n    const client = (await this.runtime()).getClient()\n    const sid = await this.session()\n    const code = `stat -c '%f|%s|%Y' ${this.shellQuote(path)} 2>/dev/null || printf 'missing'`\n    const result = await client.run(code, { sessionId: sid, timeout: 10 })\n    if (result.exitCode !== 0) throw new FsError(`cannot stat \"${path}\": ${result.stderr}`, 'FS_IO_ERROR')\n    const raw = result.stdout.trim()\n    if (raw === 'missing') return undefined\n    const parts = raw.split('|')\n    if (parts.length !== 3) return undefined\n    const typeHex = Number.parseInt(parts[0] ?? '', 16)\n    const size = Number.parseInt(parts[1] ?? '0', 10)\n    // stat -c '%f' is the full st_mode (type bits + permission bits, e.g. 41ed\n    // for a 0755 dir); mask the type bits instead of strict equality or every\n    // real file/dir parses as 'other' and reads are rejected.\n    const mode = typeHex & 0xF000\n    const type: FsInfo['type'] = mode === 0x4000 ? 'directory' : mode === 0x8000 ? 'file' : 'other'\n    const version = FsVersion(`k8e:${parts[2] ?? '0'}:${parts[1] ?? '0'}`)\n    return { type, size: Number.isFinite(size) ? size : 0, version }\n  }\n\n  override async stat(target: FsTarget, signal?: AbortSignal): Promise<FsInfo | undefined> {\n    const path = this.processPath(target)\n    if (!this.isSandboxPath(path)) {\n      const facts = await this.localStat(path)\n      if (facts === undefined) return undefined\n      return { version: facts.version, type: facts.type, ...(facts.type === 'file' ? { size: facts.size } : {}) }\n    }\n    const facts = await this.probe(path)\n    if (facts === undefined) return undefined\n    return { version: facts.version, type: facts.type, ...(facts.type === 'file' ? { size: facts.size } : {}) }\n  }\n\n  override async lstat(path: string, opts?: { cwd?: string }, signal?: AbortSignal): Promise<FsPathInfo | undefined> {\n    const displayPath = this.display(path, opts?.cwd)\n    const info = await this.stat({ targetKey: FsTargetKey(displayPath), displayPath }, signal)\n    if (info === undefined) return undefined\n    return info\n  }\n\n  override async readText(target: FsTarget, signal?: AbortSignal): Promise<string> {\n    const path = this.processPath(target)\n    try {\n      if (!this.isSandboxPath(path)) return await this.localReadText(path)\n      const client = (await this.runtime()).getClient()\n      const sid = await this.session()\n      return await client.read(sid, path)\n    } catch (cause) {\n      throw new FsError(`cannot read \"${target.displayPath}\": ${String(cause)}`, 'FS_IO_ERROR', { cause })\n    }\n  }\n\n  override async streamText(target: FsTarget, signal?: AbortSignal): Promise<AsyncIterable<string>> {\n    const content = await this.readText(target, signal)\n    return {\n      async *[Symbol.asyncIterator](): AsyncGenerator<string> {\n        if (content.length > 0) yield content\n      },\n    }\n  }\n\n  override async readBytes(target: FsTarget, signal: AbortSignal | undefined, maxBytes: number): Promise<Uint8Array> {\n    const content = await this.readText(target, signal)\n    const bytes = new TextEncoder().encode(content)\n    if (bytes.byteLength > maxBytes) {\n      throw new FsError(`cannot read \"${target.displayPath}\": ${bytes.byteLength} bytes exceeds the ${maxBytes}-byte limit`, 'FS_TOO_LARGE')\n    }\n    return bytes\n  }\n\n  override async listDir(target: FsTarget, signal?: AbortSignal): Promise<FsDirEntry[]> {\n    const path = this.processPath(target)\n    if (!this.isSandboxPath(path)) return this.localListDir(path)\n\n    const client = (await this.runtime()).getClient()\n    const sid = await this.session()\n    const prefix = path === '/' ? '/' : `${path}/`\n    const files = await client.list(sid)\n    const entries: FsDirEntry[] = []\n    for (const file of files) {\n      if (!file.path.startsWith(prefix)) continue\n      const rest = file.path.slice(prefix.length)\n      if (rest.length === 0 || rest.includes('/')) continue // only direct children\n      const childPath = file.path\n      // Entry facts (type/size) come from the single ListFiles RPC when the\n      // gateway reports them; only legacy gateways pay a per-child probe.\n      // dsh's FsInfo has no 'symlink' kind, so symlinks surface as 'other'.\n      const facts: StatFacts | undefined = file.type !== undefined\n        ? { type: file.type === 'symlink' ? 'other' : file.type, size: file.size ?? 0, version: FsVersion(`k8e:${file.modified}:${file.size ?? 0}`) }\n        : await this.probe(childPath)\n      entries.push({\n        name: rest,\n        type: facts?.type ?? 'other',\n        target: { targetKey: FsTargetKey(childPath), displayPath: childPath },\n        ...(facts?.type === 'file' ? { size: facts.size } : {}),\n        ...(facts !== undefined ? { version: facts.version } : {}),\n      })\n    }\n    return entries.sort((left, right) => left.name.localeCompare(right.name))\n  }\n\n  override async writeText(\n    target: FsTarget,\n    content: string,\n    expected?: FsWriteIntent,\n    signal?: AbortSignal,\n  ): Promise<FsWriteOutcome> {\n    const path = this.processPath(target)\n    const local = !this.isSandboxPath(path)\n    if (expected?.kind === 'createIfAbsent') {\n      const existing = await this.stat(target, signal)\n      if (existing !== undefined) {\n        throw new FsError(`cannot overwrite existing \"${target.displayPath}\" without reading it first`, 'FS_NOT_OBSERVED')\n      }\n    }\n    const existing = await this.stat(target, signal)\n    const before = existing === undefined ? null : await this.readText(target, signal)\n    if (local) {\n      await this.localWriteText(path, content)\n      const facts = await this.localStat(path)\n      return {\n        operation: existing === undefined ? 'create' : 'update',\n        version: facts?.version ?? FsVersion('host:unknown'),\n        before,\n        after: content,\n      }\n    }\n    const client = (await this.runtime()).getClient()\n    const sid = await this.session()\n    await client.write(sid, path, content)\n    const facts = await this.probe(path)\n    return {\n      operation: existing === undefined ? 'create' : 'update',\n      version: facts?.version ?? FsVersion('k8e:unknown'),\n      before,\n      after: content,\n    }\n  }\n\n  override async editText(\n    target: FsTarget,\n    edit: FsEditRequest,\n    expected?: { version: ReturnType<typeof FsVersion> },\n    signal?: AbortSignal,\n  ): Promise<FsEditOutcome> {\n    const before = await this.readText(target, signal)\n    const oldString = edit.oldString\n    if (oldString.length === 0) {\n      throw new FsError(`cannot edit \"${target.displayPath}\": old_string must be non-empty`, 'FS_EDIT_NOT_FOUND')\n    }\n    let matches = 0\n    let offset = 0\n    while (true) {\n      const found = before.indexOf(oldString, offset)\n      if (found < 0) break\n      matches += 1\n      offset = found + oldString.length\n    }\n    if (matches === 0) throw new FsError(`cannot edit \"${target.displayPath}\": old_string was not found`, 'FS_EDIT_NOT_FOUND')\n    if (!edit.replaceAll && matches !== 1) {\n      throw new FsError(`cannot edit \"${target.displayPath}\": old_string matched ${matches} times`, 'FS_AMBIGUOUS_EDIT')\n    }\n    const after = edit.replaceAll ? before.split(oldString).join(edit.newString) : before.replace(oldString, edit.newString)\n    await this.writeText(target, after, undefined, signal)\n    const path = this.processPath(target)\n    const version = this.isSandboxPath(path)\n      ? (await this.probe(path))?.version ?? FsVersion('k8e:unknown')\n      : (await this.localStat(path))?.version ?? FsVersion('host:unknown')\n    return { version, before, after }\n  }\n}\n\nexport default K8eFileSystem\n"
    }
  ],
